206	func listSourceRefsV2(ctx context.Context, conn Conn, caps *V2Capabilities, prefixes []string) ([]*plumbing.Reference, plumbing.ReferenceName, bool, []string, error) {
207		// Always include "HEAD" so the server returns the symref-target attribute
208		// for HEAD. Without this, callers that pass only "refs/heads/" or
209		// "refs/tags/" prefixes filter HEAD out of the response and lose the
210		// default-branch hint that bootstrap planning uses as a trunk cutoff.
211		args := []string{"peel", "symrefs", "ref-prefix HEAD"}
212		// Ask the server to report an unborn HEAD explicitly, so a repository
213		// with no commits says so instead of answering with no ref lines at all.
214		// Gated on the advertisement: protocol v2 forbids sending an argument the
215		// server did not advertise, and a stricter server may fail the command.
216		// Costs nothing — no extra round trip, and a source WITH commits answers
217		// exactly as before.
218		if caps.LSRefsSupports("unborn") {
219			args = append(args, "unborn")
220		}
221		for _, prefix := range prefixes {
222			args = append(args, "ref-prefix "+prefix)
223		}
224		body, err := EncodeCommand("ls-refs", caps.RequestCapabilities(), args)
225		if err != nil {
226			return nil, "", false, nil, err
227		}
228		data, err := PostRPC(ctx, conn, transport.UploadPackService, body, true, "upload-pack ls-refs")
229		if err != nil {
230			return nil, "", false, nil, err
231		}
