240	// decodeV2LSRefs decodes an ls-refs response into its refs, the branch HEAD
241	// points at, whether the server reported HEAD as unborn, and the ref names
242	// dropped as invalid for the caller to report.
243	func decodeV2LSRefs(r *bytes.Reader) ([]*plumbing.Reference, plumbing.ReferenceName, bool, []string, error) {
244		reader := NewPacketReader(r)
245		var refs []*plumbing.Reference
246		var headTarget plumbing.ReferenceName
247		var unborn bool
248		for {
249			kind, payload, err := reader.ReadPacket()
250			if err != nil {
251				return nil, "", false, nil, err
252			}
253			if kind == PacketFlush {
254				// Names come from the remote, so drop anything git would reject
255				// and hand the list back for the caller to report. unborn rides
256				// alongside rather than through this filter: it is a property of
257				// the repository, not a ref, and the line that carries it is
258				// consumed below without ever entering refs.
259				valid, skipped := PartitionRefNames(refs)
260				return valid, headTarget, unborn, skipped, nil
261			}
262			if kind != PacketData {
263				return nil, "", false, nil, fmt.Errorf("unexpected packet type %v in ls-refs response", kind)
264			}
265			fields := strings.Fields(strings.TrimSpace(string(payload)))
266			if len(fields) < 2 {
267				return nil, "", false, nil, fmt.Errorf("malformed ls-refs response line %q", payload)
268			}
269			if fields[0] == "unborn" {
270				// "unborn HEAD symref-target:refs/heads/main": the repository has
271				// no commits. Recorded as a flag only — headTarget deliberately
272				// stays empty, because consumers treat a non-empty HeadTarget as
273				// a branch that exists on the source (mirror-pipeline's
274				// default-branch reconcile drives SetDefaultBranch off it), and
275				// an unborn target does not.
276				if fields[1] == string(plumbing.HEAD) {
277					unborn = true
278				}
279				continue
280			}
281			hash := plumbing.NewHash(fields[0])
282			name := plumbing.ReferenceName(fields[1])
283			if name == plumbing.HEAD {
284				// HEAD is surfaced via headTarget only; not appended to the ref
285				// slice because it is a symbolic ref, matching v1 behavior where
286				// symrefs are filtered out by downstream RefHashMap.
287				for _, attr := range fields[2:] {
288					if target, ok := strings.CutPrefix(attr, "symref-target:"); ok {
289						headTarget = plumbing.ReferenceName(target)
290						break
291					}
292				}
293				continue
294			}
295			refs = append(refs, plumbing.NewHashReference(name, hash))
296		}
297	}
