}

// current: PruneTarget, which normalizes per call
func BenchmarkAddPruneCandidatesNow(b *testing.B) {
	targets := probeTargets(100_000)
	cfg := normalizeAllRefs(probeCfg())
	b.ResetTimer()
	for b.Loop() {
		managed := make(map[plumbing.ReferenceName]ManagedTarget, len(targets))
		addPruneCandidates(managed, targets, cfg)
	}
}

// previous shape: switch inline, no per-ref normalization
func addPruneCandidatesInline(managed map[plumbing.ReferenceName]ManagedTarget, targetRefs map[plumbing.ReferenceName]plumbing.Hash, cfg PlanConfig) {
	for targetRef := range targetRefs {
		if _, ok := managed[targetRef]; ok {
			continue
		}
		if IsRefExcluded(targetRef, cfg.ExcludeRefPrefixes, cfg.ExcludeRefs) {
			continue
		}
		switch {
		case targetRef.IsTag() && (cfg.IncludeTags || cfg.AllRefs):
			managed[targetRef] = ManagedTarget{Kind: RefKindTag, Label: targetRef.Short()}
		case targetRef.IsBranch() && len(cfg.Mappings) == 0 && len(cfg.Branches) == 0:
			managed[targetRef] = ManagedTarget{Kind: RefKindBranch, Label: targetRef.Short()}
		case cfg.AllRefs && RefKindFromName(targetRef) == RefKindOther && len(cfg.Mappings) == 0:
			managed[targetRef] = ManagedTarget{Kind: RefKindOther, Label: targetRef.Short()}
		}
	}
