// classifyEmptySource reports whether err means "planning found no refs to
// apply", and if so which of the four cases it is.
//
// The typed sentinels are checked first and the historical message substring
// last. That ordering is deliberate: it is the only part of this function that
// survives a git-sync version skew in either direction — an older vendored
// git-sync raises only the untyped error, a newer one raises the sentinels, and
// this classifies both without caring which is linked. The substring match
// (consistent with permanentStatusHints below) is what an unopted-in or
// non-entiredb sync still produces, so it cannot be dropped.
func classifyEmptySource(err error) (emptySourceReason, bool) {
	switch {
	case err == nil:
		return "", false
	case errors.Is(err, gitsync.ErrSourceEmptyTargetPopulated):
		return emptyReasonDiverged, true
	case errors.Is(err, gitsync.ErrSourceEmptyUnverified):
		return emptyReasonUnverified, true
	case errors.Is(err, gitsync.ErrNoRefsSelected):
		return emptyReasonUnselected, true
	case strings.Contains(err.Error(), "no source refs matched"):
		return emptyReasonLegacy, true
	default:
		return "", false
	}
}

